"use strict";
function log(...a) { console.log(String(a.map((x) => String(x)).join(" | "))); }
class Base {
  constructor() { this.opts = { p: "k:" }; this.set1 = new Set(); this.names = {}; }
  addCmd(name) { this.set1.add(name); this[name] = mk(name); this[name + "Buffer"] = mk(name + "Buffer"); }
  hello() { return "base-hello"; }
  send(n, a) { return n + "(" + a.join(",") + ")" + this.opts.p; }
  bindTo(other) {
    for (const k of ["hello", "send"]) { this[k] = this[k].bind(other); }
  }
}
const names = ["get", "set", "exec", "del"];
names.forEach(function (n) { Base.prototype[n] = mk(n); });
function mk(n) { return function (...args) { return this.send(n, args); }; }
class Sub extends Base {
  exec(x) { return "sub-exec:" + x + "/" + super.hello(); }
  hello() { return "sub-hello>" + super.hello(); }
  both() { return [this.hello(), this.exec("e")]; }
}
class Pipe extends Base {
  constructor(src) {
    super();
    src.set1.forEach((name) => {
      this[name] = src[name];
      this[name + "Buffer"] = src[name + "Buffer"];
    });
  }
  run(c, a) { return this[c].apply(this, a); }
}
exports.run = function () {
  const b = new Base();
  const s = new Sub();
  log(b.get("a"), s.get("b"), s.exec("c"), s.both());
  b.addCmd("zap");
  log(b.zap(1));
  log(b.zapBuffer(2));
  const kk = "zap";
  log(typeof b[kk]);
  log(b[kk](3));
  log(b["zap"](3));
  const k = "get";
  log(typeof b[k], b[k] === b.get, s[k] === b.get, typeof b["nope"], b["nope"]);
  const p = new Pipe(b);
  log(p.zap(7), p.run("zap", [8]), p.run("get", [9]), p.run("hello", []));
  const o1 = new Sub();
  o1.opts = { p: "o:" };
  s.bindTo(o1);
  log(s.hello(), s.send("x", [1]), s.both());
  const o2 = new Base();
  o2.opts = { p: "q:" };
  b.bindTo(o2);
  log(b.hello(), b.send("y", [2]));
};
